-- (migra-072: sustituye a la 071, que buscaba el parrafo anterior a migra-066 y en produccion no cambio nada)
-- 25/09/2026. «¿Que es Deltha?», primer parrafo, en los nueve idiomas: la red social para medios y voces independientes va primero
-- (visibilidad que pierden al desaparecer de los resultados de busqueda), y el agregador de enlaces queda al final. Sin dos puntos.
-- REPLACE con el texto exacto que dejo migra-066 (y, por si acaso, el anterior de migra-044/050/063): si la pagina se edito en admin y ya no coincide, no se toca
-- (comprobar en admin > Paginas). Texto acordado con Angel.
SET NAMES utf8mb4;
UPDATE pages SET body = REPLACE(body, '{site} es cuatro cosas a la vez: <b>un agregador de noticias</b>, donde la gente envía enlaces y decide con sus votos qué llega a sus dos portadas, Medios y Substacks; <b>un lector de fuentes</b>, que recoge por RSS lo que publican medios, newsletters y otros agregadores y lo muestra, sin algoritmo, de lo más reciente a lo más antiguo; <b>una red social contralgorítmica</b>, sin máquina que elija por ti qué ver; y <b>un espacio para el debate</b>, con hilos que se abren, se discuten y se cierran.', '{site} es <b>una red social para medios y voces independientes</b>. Nace para devolverles la visibilidad que van perdiendo a medida que desaparecen de los resultados de búsqueda. Cada cabecera y cada autor publica lo suyo y aquí se lee tal como llega por RSS, de lo más reciente a lo más antiguo, sin algoritmo que decida por nadie. Es también <b>una red contralgorítmica</b> que prescinde de recomendaciones interesadas; <b>un espacio para el debate</b>, con hilos que se abren, se discuten y se cierran; y <b>un agregador de enlaces</b>, donde la gente comparte lo que encuentra y decide con sus votos qué llega a portada.') WHERE slug = 'que-es';
UPDATE pages SET body = REPLACE(body, '{site} és quatre coses alhora: <b>un agregador de notícies</b>, on la gent envia enllaços i decideix amb els seus vots què arriba a les seves dues portades, Mitjans i Substacks; <b>un lector de fonts</b>, que recull per RSS el que publiquen mitjans, butlletins i altres agregadors i ho mostra, sense algorisme, del més nou al més antic; <b>una xarxa social contraalgorítmica</b>, sense cap màquina que triï per tu què has de veure; i <b>un espai per al debat</b>, amb fils que s''obren, es discuteixen i es tanquen.', '{site} és <b>una xarxa social per a mitjans i veus independents</b>. Neix per retornar-los la visibilitat que van perdent a mesura que desapareixen dels resultats de cerca. Cada capçalera i cada autor publica el que és seu i aquí es llegeix tal com arriba per RSS, del més nou al més antic, sense cap algorisme que decideixi per ningú. És també <b>una xarxa contraalgorítmica</b> que prescindeix de recomanacions interessades; <b>un espai per al debat</b>, amb fils que s''obren, es discuteixen i es tanquen; i <b>un agregador d''enllaços</b>, on la gent comparteix el que troba i decideix amb els seus vots què arriba a portada.') WHERE slug = 'que-es.ca';
UPDATE pages SET body = REPLACE(body, '{site} ist vier Dinge zugleich: <b>ein Nachrichten-Aggregator</b>, in dem Leute Links einreichen und mit ihren Stimmen entscheiden, was auf seine zwei Titelseiten kommt, Medien und Substacks; <b>ein Quellen-Reader</b>, der per RSS sammelt, was Medien, Newsletter und andere Aggregatoren veröffentlichen, und es ohne Algorithmus zeigt, das Neueste zuerst; <b>ein gegenalgorithmisches soziales Netzwerk</b>, ohne Maschine, die für dich auswählt, was du siehst; und <b>ein Ort für Debatten</b>, mit Threads, die eröffnet, diskutiert und wieder geschlossen werden.', '{site} ist <b>ein soziales Netzwerk für Medien und unabhängige Stimmen</b>. Es entsteht, um ihnen die Sichtbarkeit zurückzugeben, die sie verlieren, während sie aus den Suchergebnissen verschwinden. Jedes Medium und jeder Autor veröffentlicht das Eigene, und hier wird es so gelesen, wie es per RSS ankommt, das Neueste zuerst, ohne Algorithmus, der für irgendjemanden entscheidet. Es ist auch <b>ein gegenalgorithmisches Netzwerk</b>, das auf interessengeleitete Empfehlungen verzichtet; <b>ein Ort für Debatten</b>, mit Threads, die eröffnet, diskutiert und wieder geschlossen werden; und <b>ein Link-Aggregator</b>, in dem Leute teilen, was sie finden, und mit ihren Stimmen entscheiden, was auf die Titelseite kommt.') WHERE slug = 'que-es.de';
UPDATE pages SET body = REPLACE(body, '{site} is four things at once: <b>a news aggregator</b>, where people submit links and their votes decide what makes its two front pages, Media and Substacks; <b>a feed reader</b>, which picks up via RSS what media outlets, newsletters and other aggregators publish and shows it, with no algorithm, newest first; <b>a counter-algorithmic social network</b>, with no machine choosing what you see; and <b>a place for debate</b>, with threads that open, get argued over and then close.', '{site} is <b>a social network for media outlets and independent voices</b>. It exists to give them back the visibility they are losing as they vanish from search results. Every outlet and every author publishes their own work, and here it is read just as it arrives via RSS, newest first, with no algorithm deciding for anyone. It is also <b>a counter-algorithmic network</b> that does without self-interested recommendations; <b>a place for debate</b>, with threads that open, get argued over and then close; and <b>a link aggregator</b>, where people share what they find and their votes decide what makes the front page.') WHERE slug = 'que-es.en';
UPDATE pages SET body = REPLACE(body, '{site} lau gauza da aldi berean: <b>albiste-agregatzaile bat</b>, non jendeak estekak bidaltzen dituen eta botoekin erabakitzen duen zer iristen den bere bi azaletara, Hedabideak eta Substackak; <b>iturri-irakurle bat</b>, hedabideek, buletinek eta beste agregatzaile batzuek argitaratzen dutena RSS bidez jaso eta algoritmorik gabe erakusten duena, berrienetik hasita; <b>sare sozial kontralgoritmiko bat</b>, zer ikusi behar duzun zure ordez aukeratzen duen makinarik gabe; eta <b>eztabaidarako gune bat</b>, ireki, eztabaidatu eta itxi egiten diren hariekin.', '{site} <b>hedabideentzako eta ahots independenteentzako sare sozial bat</b> da. Bilaketa-emaitzetatik desagertu ahala galtzen ari diren ikusgaitasuna itzultzeko jaio da. Goiburu bakoitzak eta egile bakoitzak berea argitaratzen du, eta hemen RSS bidez iristen den bezala irakurtzen da, berrienetik zaharrenera, inoren ordez erabakitzen duen algoritmorik gabe. Bada ere <b>sare kontralgoritmiko bat</b>, interesatutako gomendioei uko egiten diena; <b>eztabaidarako gune bat</b>, ireki, eztabaidatu eta itxi egiten diren hariekin; eta <b>esteka-agregatzaile bat</b>, non jendeak aurkitzen duena partekatzen duen eta botoekin erabakitzen duen zer iristen den azalera.') WHERE slug = 'que-es.eu';
UPDATE pages SET body = REPLACE(body, '{site}, c''est quatre choses à la fois : <b>un agrégateur d''actualités</b>, où les gens envoient des liens et décident par leurs votes de ce qui arrive sur ses deux unes, Médias et Substacks ; <b>un lecteur de sources</b>, qui récupère par RSS ce que publient des médias, des newsletters et d''autres agrégateurs et l''affiche, sans algorithme, du plus récent au plus ancien ; <b>un réseau social contre-algorithmique</b>, sans machine qui choisit pour toi ce que tu vois ; et <b>un espace de débat</b>, avec des fils qui s''ouvrent, se discutent et se ferment.', '{site} est <b>un réseau social pour les médias et les voix indépendantes</b>. Il naît pour leur rendre la visibilité qu''ils perdent à mesure qu''ils disparaissent des résultats de recherche. Chaque titre et chaque auteur publie ce qui est à lui, et ici on le lit tel qu''il arrive par RSS, du plus récent au plus ancien, sans algorithme qui décide pour personne. C''est aussi <b>un réseau contre-algorithmique</b> qui se passe des recommandations intéressées ; <b>un espace de débat</b>, avec des fils qui s''ouvrent, se discutent et se ferment ; et <b>un agrégateur de liens</b>, où les gens partagent ce qu''ils trouvent et décident par leurs votes de ce qui arrive en une.') WHERE slug = 'que-es.fr';
UPDATE pages SET body = REPLACE(body, '{site} é catro cousas á vez: <b>un agregador de novas</b>, onde a xente envía ligazóns e decide cos seus votos que chega ás súas dúas portadas, Medios e Substacks; <b>un lector de fontes</b>, que recolle por RSS o que publican medios, boletíns e outros agregadores e o amosa, sen algoritmo, do máis novo ao máis vello; <b>unha rede social contralgorítmica</b>, sen máquina que escolla por ti que ver; e <b>un espazo para o debate</b>, con fíos que se abren, se discuten e se pechan.', '{site} é <b>unha rede social para medios e voces independentes</b>. Nace para devolverlles a visibilidade que van perdendo a medida que desaparecen dos resultados de busca. Cada cabeceira e cada autor publica o seu e aquí lese tal como chega por RSS, do máis novo ao máis vello, sen algoritmo que decida por ninguén. É tamén <b>unha rede contralgorítmica</b> que prescinde de recomendacións interesadas; <b>un espazo para o debate</b>, con fíos que se abren, se discuten e se pechan; e <b>un agregador de ligazóns</b>, onde a xente comparte o que atopa e decide cos seus votos que chega á portada.') WHERE slug = 'que-es.gl';
UPDATE pages SET body = REPLACE(body, '{site} è quattro cose insieme: <b>un aggregatore di notizie</b>, dove la gente invia link e decide con i propri voti cosa arriva nelle sue due prime pagine, Media e Substack; <b>un lettore di fonti</b>, che raccoglie via RSS ciò che pubblicano testate, newsletter e altri aggregatori e lo mostra, senza algoritmo, dal più recente al più vecchio; <b>un social network controalgoritmico</b>, senza una macchina che scelga per te cosa vedere; e <b>uno spazio di dibattito</b>, con discussioni che si aprono, si accendono e si chiudono.', '{site} è <b>un social network per i media e le voci indipendenti</b>. Nasce per restituire loro la visibilità che vanno perdendo man mano che scompaiono dai risultati di ricerca. Ogni testata e ogni autore pubblica il proprio lavoro e qui lo si legge così come arriva via RSS, dal più recente al più vecchio, senza un algoritmo che decida per nessuno. È anche <b>una rete controalgoritmica</b> che fa a meno delle raccomandazioni interessate; <b>uno spazio di dibattito</b>, con discussioni che si aprono, si accendono e si chiudono; e <b>un aggregatore di link</b>, dove la gente condivide ciò che trova e decide con i propri voti cosa arriva in prima pagina.') WHERE slug = 'que-es.it';
UPDATE pages SET body = REPLACE(body, '{site} é quatro coisas ao mesmo tempo: <b>um agregador de notícias</b>, onde as pessoas enviam links e decidem com os seus votos o que chega às suas duas capas, Meios e Newsletters; <b>um leitor de fontes</b>, que recolhe por RSS o que publicam meios, newsletters e outros agregadores e o mostra, sem algoritmo, do mais recente ao mais antigo; <b>uma rede social contralgorítmica</b>, sem máquina que escolha em seu lugar o que ver; e <b>um espaço para o debate</b>, com conversas que se abrem, se discutem e se fecham.', '{site} é <b>uma rede social para meios e vozes independentes</b>. Nasce para lhes devolver a visibilidade que vão perdendo à medida que desaparecem dos resultados de pesquisa. Cada cabeçalho e cada autor publica o que é seu e aqui lê-se tal como chega por RSS, do mais recente ao mais antigo, sem algoritmo que decida por ninguém. É também <b>uma rede contralgorítmica</b> que prescinde de recomendações interessadas; <b>um espaço para o debate</b>, com conversas que se abrem, se discutem e se fecham; e <b>um agregador de links</b>, onde as pessoas partilham o que encontram e decidem com os seus votos o que chega à capa.') WHERE slug = 'que-es.pt';
